// W6.9 slice 4: uploaded fonts in Preferences ▸ Fonts (design section 5). Upload a font, see it listed,
// refuse a restricted and a garbage file, reload and see the font still there (the start-up sync),
// remove it and see it gone after a reload, then clear all local data. Browsers that cannot keep
// fonts (no writable private storage) assert the session-only hint instead of the reload steps.
// The fixtures are generated by scripts/make_fixtures.py (generate_fonts), none is committed. No PDF
// is saved, so there is no host check here.
import { expect, type Page, test } from '@playwright/test';
import { fixture, openApp, STAGED, watchPage } from './support';

async function openPreferences(page: Page) {
  await page.getByRole('button', { name: 'Preferences…', exact: true }).click();
  const dialog = page.getByRole('dialog').first();
  await expect(dialog).toBeVisible();
  return dialog;
}

// Whether this browser keeps a file in private storage the way the app needs: a probe file that
// can be written, then removed.
async function canKeepFonts(page: Page): Promise<boolean> {
  return page.evaluate(async () => {
    try {
      const root = await navigator.storage.getDirectory();
      const handle = await root.getFileHandle('elanero-probe.tmp', { create: true });
      const writable = await handle.createWritable();
      await writable.close();
      await root.removeEntry('elanero-probe.tmp');
      return true;
    } catch {
      return false;
    }
  });
}

async function hasFontsFolder(page: Page): Promise<boolean> {
  return page.evaluate(async () => {
    try {
      const root = await navigator.storage.getDirectory();
      await root.getDirectoryHandle('fonts');
      return true;
    } catch {
      return false;
    }
  });
}

test.describe('engine staged', () => {
  test.skip(!STAGED, 'engine assets are not staged (scripts/stage_engine_assets.mjs); not run');

  test('upload, refuse, reload, remove, and clear uploaded fonts', async ({ page }) => {
    const problems = watchPage(page);
    await openApp(page);
    let dialog = await openPreferences(page);
    const picker = dialog.locator('input[type="file"]');
    const rows = dialog.getByRole('listitem');

    // 1. A font is added, listed by its family, and says so.
    await picker.setInputFiles({
      name: 'TestSans-Regular.ttf',
      mimeType: 'font/ttf',
      buffer: fixture('fonts/TestSans-Regular.ttf'),
    });
    await expect(rows.filter({ hasText: 'Test Sans' })).toBeVisible({ timeout: 60_000 });
    await expect(dialog.getByRole('status')).toContainText('TestSans-Regular.ttf was added.');

    // 2. A restricted font and a garbage file, together: each gets its own refusal, no new rows.
    await picker.setInputFiles([
      {
        name: 'TestRestricted-Regular.ttf',
        mimeType: 'font/ttf',
        buffer: fixture('fonts/TestRestricted-Regular.ttf'),
      },
      { name: 'Garbage.ttf', mimeType: 'font/ttf', buffer: fixture('fonts/Garbage.ttf') },
    ]);
    await expect(dialog.getByRole('alert')).toContainText(
      "TestRestricted-Regular.ttf can't be added: its licence does not allow embedding it in documents.",
    );
    await expect(dialog.getByRole('alert')).toContainText(
      'Garbage.ttf is not a font file that can be read.',
    );
    await expect(rows).toHaveCount(1);

    if (!(await canKeepFonts(page))) {
      // No writable private storage: the font works for this tab only, and the section says so.
      await expect(
        dialog.getByText("This browser can't keep fonts after the tab closes."),
      ).toBeVisible();
      await expect(dialog.getByRole('button', { name: 'Upload font…' })).toBeVisible();
      expect(problems).toEqual([]);
      return;
    }

    // 3. Reload: the kept font is still listed (the start-up sync sends it to the new engine).
    await page.reload();
    await openApp(page);
    dialog = await openPreferences(page);
    await expect(dialog.getByRole('listitem').filter({ hasText: 'Test Sans' })).toBeVisible({
      timeout: 60_000,
    });

    // 4. Remove it and confirm: gone at once, gone after a reload, and no fonts folder is left.
    await dialog.getByRole('button', { name: 'Remove TestSans-Regular.ttf', exact: true }).click();
    await dialog.getByRole('group').getByRole('button', { name: 'Remove', exact: true }).click();
    await expect(dialog.getByRole('listitem').filter({ hasText: 'Test Sans' })).toHaveCount(0);
    await page.reload();
    await openApp(page);
    dialog = await openPreferences(page);
    await expect(dialog.getByText('No fonts uploaded.')).toBeVisible({ timeout: 60_000 });
    expect(await hasFontsFolder(page)).toBe(false);

    // 5. Upload again, then Clear all local data: after the reload the list is empty and the folder
    // is gone.
    await dialog.locator('input[type="file"]').setInputFiles({
      name: 'TestSans-Regular.ttf',
      mimeType: 'font/ttf',
      buffer: fixture('fonts/TestSans-Regular.ttf'),
    });
    await expect(dialog.getByRole('status')).toContainText('TestSans-Regular.ttf was added.');
    await dialog.getByRole('button', { name: 'Clear all local data…', exact: true }).click();
    // Clear reloads the page; the load is awaited with the click, not after it.
    await Promise.all([
      page.waitForEvent('load'),
      dialog.getByRole('group').getByRole('button', { name: 'Clear', exact: true }).click(),
    ]);
    await openApp(page);
    dialog = await openPreferences(page);
    await expect(dialog.getByText('No fonts uploaded.')).toBeVisible({ timeout: 60_000 });
    expect(await hasFontsFolder(page)).toBe(false);

    // 6. No content security policy violation along the way.
    expect(problems).toEqual([]);
  });
});
